let uidSeed = Date.now();

function uid(): number {
	return uidSeed++;
}

function isArray<T = unknown>(obj: unknown): obj is T[] {
	if (Array.isArray) {
		return Array.isArray(obj);
	}

	return !!(
		obj &&
		typeof obj === "object" &&
		"length" in obj &&
		(obj as { pop?: unknown }).pop &&
		(obj as { push?: unknown }).push
	);
}

function isStringObject(obj: unknown): obj is String {
	return !!(
		obj &&
		typeof obj === "object" &&
		Function.prototype.toString.call((obj as object).constructor) ===
			"function String() { [native code] }"
	);
}

function isNumberObject(obj: unknown): obj is Number {
	return !!(
		obj &&
		typeof obj === "object" &&
		Function.prototype.toString.call((obj as object).constructor) ===
			"function Number() { [native code] }"
	);
}

function isBooleanObject(obj: unknown): obj is Boolean {
	return !!(
		obj &&
		typeof obj === "object" &&
		Function.prototype.toString.call((obj as object).constructor) ===
			"function Boolean() { [native code] }"
	);
}

function isDate(obj: unknown): obj is Date {
	return !!(
		obj &&
		typeof obj === "object" &&
		(obj as { getFullYear?: unknown }).getFullYear &&
		(obj as { getMonth?: unknown }).getMonth &&
		(obj as { getDate?: unknown }).getDate
	);
}

function defined<T>(obj: T | undefined): obj is T {
	return typeof obj !== "undefined";
}

type DelayedFunction<T extends (...args: any[]) => void> = {
	(...args: Parameters<T>): void;
	$pending: boolean;
	$cancelTimeout: () => void;
	$execute: (...args: Parameters<T>) => void;
};

function delay<T extends (...args: any[]) => void>(
	callback: T,
	timeout: number
): DelayedFunction<T> {
	let timer: ReturnType<typeof setTimeout>;

	const result = function (...args: Parameters<T>) {
		result.$cancelTimeout();
		result.$pending = true;

		timer = setTimeout(function (this: unknown) {
			callback.apply(this, args);
			result.$pending = false;
		}, timeout);
	} as DelayedFunction<T>;

	result.$pending = false;

	result.$cancelTimeout = function () {
		clearTimeout(timer);
		result.$pending = false;
	};

	result.$execute = function (...args: Parameters<T>) {
		callback.apply(this, args);
		result.$cancelTimeout();
	};

	return result;
}

function mixin<T extends object, S extends object>(
	target: T,
	source: S,
	force?: boolean
): T & S {
	const targetObj = target as Record<string, unknown>;
	const sourceObj = source as Record<string, unknown>;

	for (const f in sourceObj) {
		if (targetObj[f] === undefined || force) {
			targetObj[f] = sourceObj[f];
		}
	}

	return target as T & S;
}

function copy<T>(object: T): T {
	let result: any;

	if (object && typeof object === "object") {
		switch (true) {
			case isDate(object):
				result = new Date(object);
				break;

			case isArray(object):
				result = new Array(object.length);

				for (let i = 0; i < object.length; i++) {
					result[i] = copy(object[i]);
				}

				break;

			case isStringObject(object):
				result = new String(object);
				break;

			case isNumberObject(object):
				result = new Number(object);
				break;

			case isBooleanObject(object):
				result = new Boolean(object);
				break;

			default:
				result = {};

				for (const i in object) {
					if (Object.prototype.hasOwnProperty.call(object, i)) {
						const value = object[i];
						const varType = typeof value;

						if (
							varType === "string" ||
							varType === "number" ||
							varType === "boolean"
						) {
							result[i] = value;
						} else if (isDate(value)) {
							result[i] = new Date(value);
						} else {
							result[i] = copy(value);
						}
					}
				}

				break;
		}
	}

	return result || object;
}

export default {
	uid,
	mixin,
	copy,
	defined,
	isDate,
	delay
};