/**
 * Id lookup over `scheduler._rendered`.
 *
 * `_rendered` is a flat array of the DOM nodes currently on screen. Finding the
 * nodes of one event used to mean walking the whole array and reading an
 * attribute off every node, so refreshing N events cost O(N^2) attribute reads.
 * This index keeps a bucket of nodes per event id so a lookup is O(1).
 *
 * The array stays the source of truth. The index tracks how much of it has been
 * indexed and repairs itself:
 *
 *   - the array was replaced, or got shorter behind our back -> full rebuild
 *   - the array grew -> index the new tail only (nodes are always appended)
 *
 * so code that manipulates `_rendered` directly keeps working, just without the
 * speed-up on that particular operation.
 *
 * Two rules for the render code:
 *
 *   - set the event attribute on a node before pushing it into `_rendered`, the
 *     index reads the id off the node when it catches up with the array;
 *   - go through `scheduler._reset_rendered_events()` instead of assigning a new
 *     empty array, so the index lets go of the nodes it was holding.
 */

const EMPTY = [];

export default function createRenderedEventsIndex(scheduler) {
	let buckets = null;
	let source = null;
	let indexed = 0;
	let anchor = null; //last node we indexed, to notice edits we were not told about

	function idOf(node) {
		return node.getAttribute(scheduler.config.event_attribute);
	}

	function add(node) {
		const id = idOf(node);
		if (id === null) return;

		const bucket = buckets.get(id);
		if (bucket) bucket.push(node);
		else buckets.set(id, [node]);
	}

	function markIndexed() {
		anchor = indexed > 0 ? source[indexed - 1] : null;
	}

	function rebuild(rendered) {
		buckets = new Map();
		source = rendered;
		indexed = rendered.length;

		for (let i = 0; i < rendered.length; i++) add(rendered[i]);
		markIndexed();
	}

	return {
		/** Brings the index in step with the array. Cheap when nothing changed. */
		sync() {
			const rendered = scheduler._rendered;

			const outOfStep = buckets === null ||
				source !== rendered ||
				rendered.length < indexed ||
				(indexed > 0 && rendered[indexed - 1] !== anchor);

			if (outOfStep) {
				rebuild(rendered);
				return;
			}

			if (indexed === rendered.length) return;

			for (; indexed < rendered.length; indexed++) add(rendered[indexed]);
			markIndexed();
		},

		/**
		 * @returns {Array} nodes rendered for the event, in insertion order.
		 * The array belongs to the index - read it, do not keep or modify it.
		 */
		lookup(id) {
			this.sync();
			return buckets.get(String(id)) || EMPTY;
		},

		/** Call after the node has been taken out of `_rendered`. */
		forget(node) {
			if (buckets === null) return;

			const id = idOf(node);
			const bucket = id === null ? null : buckets.get(id);

			if (bucket) {
				const at = bucket.indexOf(node);
				if (at > -1) bucket.splice(at, 1);
				if (!bucket.length) buckets.delete(id);
			}
			if (indexed > 0) indexed--;
			markIndexed();
		},

		/** Drops the index. Needed when the id of a rendered event changes. */
		invalidate() {
			buckets = null;
			source = null;
			indexed = 0;
			anchor = null;
		}
	};
}
