interface Position {
	x: number;
	y: number;
	width: number;
	height: number;
	right: number;
	bottom: number;
}

interface OffsetPosition {
	top: number;
	left: number;
}

type ClassNameNode = Element & {
	className: SVGAnimatedString;
	currentStyle?: CSSStyleDeclaration;
};

type FocusableNode = HTMLElement & {
	$position?: number;
};

type LegacyElement = Element & {
	msMatchesSelector?: (selector: string) => boolean;
	webkitMatchesSelector?: (selector: string) => boolean;
};

function elementPosition(elem: HTMLElement): Position {
	let top = 0;
	let left = 0;
	let right = 0;
	let bottom = 0;
	const originalElem = elem;

	if (elem.getBoundingClientRect) {
		const box = elem.getBoundingClientRect();
		const body = document.body;
		const docElem = document.documentElement || document.body.parentNode || document.body;

		const scrollTop = window.pageYOffset || docElem.scrollTop || body.scrollTop;
		const scrollLeft = window.pageXOffset || docElem.scrollLeft || body.scrollLeft;
		const clientTop = docElem.clientTop || body.clientTop || 0;
		const clientLeft = docElem.clientLeft || body.clientLeft || 0;

		top = box.top + scrollTop - clientTop;
		left = box.left + scrollLeft - clientLeft;

		right = document.body.offsetWidth - box.right;
		bottom = document.body.offsetHeight - box.bottom;
	} else {
		let currentElem: HTMLElement | null = elem;

		while (currentElem) {
			top += parseInt(String(currentElem.offsetTop), 10);
			left += parseInt(String(currentElem.offsetLeft), 10);
			currentElem = currentElem.offsetParent as HTMLElement | null;
		}

		right = document.body.offsetWidth - originalElem.offsetWidth - left;
		bottom = document.body.offsetHeight - originalElem.offsetHeight - top;
	}

	return {
		y: Math.round(top),
		x: Math.round(left),
		width: originalElem.offsetWidth,
		height: originalElem.offsetHeight,
		right: Math.round(right),
		bottom: Math.round(bottom),
	};
}

function getRelativeEventPosition(ev: MouseEvent, node: HTMLElement): { x: number; y: number } {
	const d = document.documentElement;
	const box = elementPosition(node);

	return {
		x: ev.clientX - d.clientLeft - box.x + node.scrollLeft,
		y: ev.clientY - d.clientTop - box.y + node.scrollTop,
	};
}

function getNodePosition(elem: HTMLElement): Position {
	return elementPosition(elem);
}

function getClassName(node?: ClassNameNode | null): string {
	if (!node) return "";

	let className = node.className || "";

	if (typeof className !== "string" && node.className.baseVal) {
		className = node.className.baseVal;
	}

	if (typeof className !== "string" || !className.indexOf) {
		className = "";
	}

	return className || "";
}

function getTargetNode(e: Event | Element): EventTarget | null {
	let trg: EventTarget | null;

	if ("tagName" in e) {
		trg = e;
	} else {
		const event = e || window.event;
		trg = event.target || (event as any).srcElement;

		if ((trg as Element)?.shadowRoot && event.composedPath) {
			trg = event.composedPath()[0];
		}
	}

	return trg;
}

function locateCss(
	e: Event | { target?: Element | null; srcElement?: Element | null },
	classname: string,
	strict = true
): Element | null {
	let trg = ((e.target || ("srcElement" in e ? e.srcElement : null)) as Element | null);

	while (trg) {
		const css = getClassName(trg as ClassNameNode);

		if (css) {
			const ind = css.indexOf(classname);

			if (ind >= 0) {
				if (!strict) return trg;

				const left = ind === 0 || !((css.charAt(ind - 1) || "").trim());
				const right =
					ind + classname.length >= css.length ||
					!css.charAt(ind + classname.length).trim();

				if (left && right) return trg;
			}
		}

		trg = trg.parentNode as Element | null;
	}

	return null;
}

function isVisible(node: HTMLElement): boolean {
	let display: string | false = false;
	let visibility: string | false = false;

	if (window.getComputedStyle) {
		const style = window.getComputedStyle(node, null);
		display = style.display;
		visibility = style.visibility;
	} else if ((node as any).currentStyle) {
		display = (node as any).currentStyle.display;
		visibility = (node as any).currentStyle.visibility;
	}

	let hiddenSection = false;
	const recurringSection = locateCss({ target: node }, "dhx_form_repeat", false) as HTMLElement | null;

	if (recurringSection) {
		hiddenSection = recurringSection.style.height === "0px";
	}

	hiddenSection = hiddenSection || !node.offsetHeight;

	return display !== "none" && visibility !== "hidden" && !hiddenSection;
}

function hasNonNegativeTabIndex(node: HTMLElement): boolean {
	const tabIndex = node.getAttribute("tabindex");
	return tabIndex !== null && !Number.isNaN(Number(tabIndex)) && Number(tabIndex) >= 0;
}

function hasHref(node: HTMLElement): boolean {
	const canHaveHref: Record<string, boolean> = {
		a: true,
		area: true,
	};

	if (canHaveHref[node.nodeName.toLowerCase()]) {
		return !!node.getAttribute("href");
	}

	return true;
}

function isEnabled(node: HTMLElement): boolean {
	const canDisable: Record<string, boolean> = {
		input: true,
		select: true,
		textarea: true,
		button: true,
		object: true,
	};

	if (canDisable[node.nodeName.toLowerCase()]) {
		return !node.hasAttribute("disabled");
	}

	return true;
}

function getFocusableNodes(root: ParentNode): FocusableNode[] {
	const nodes = root.querySelectorAll<FocusableNode>(
		[
			"a[href]",
			"area[href]",
			"input",
			"select",
			"textarea",
			"button",
			"iframe",
			"object",
			"embed",
			"[tabindex]",
			"[contenteditable]",
		].join(", ")
	);

	const nodesArray = Array.from(nodes);

	for (let i = 0; i < nodesArray.length; i++) {
		nodesArray[i].$position = i;
	}

	nodesArray.sort((a, b) => {
		if (a.tabIndex === 0 && b.tabIndex !== 0) return 1;
		if (a.tabIndex !== 0 && b.tabIndex === 0) return -1;

		if (a.tabIndex === b.tabIndex) {
			return (a.$position || 0) - (b.$position || 0);
		}

		return a.tabIndex < b.tabIndex ? -1 : 1;
	});

	for (let i = 0; i < nodesArray.length; i++) {
		const node = nodesArray[i];
		const isValid =
			(hasNonNegativeTabIndex(node) || isEnabled(node) || hasHref(node)) &&
			isVisible(node);

		if (!isValid) {
			nodesArray.splice(i, 1);
			i--;
		}
	}

	return nodesArray;
}

function isShadowDomSupported(): boolean {
	const head = document.head as any;

	return !!(head.createShadowRoot || head.attachShadow);
}

function getActiveElement(): Element | Node | null {
	let activeElement: Element | Node | null = document.activeElement;

	if ((activeElement as Element)?.shadowRoot) {
		activeElement = (activeElement as Element).shadowRoot?.activeElement || activeElement;
	}

	if (activeElement === document.body && document.getSelection) {
		activeElement = document.getSelection()?.focusNode || document.body;
	}

	return activeElement;
}

function closest(element: LegacyElement, selector: string): Element | null {
	if (typeof element.closest === "function") {
		return element.closest(selector);
	}

	let el: Element | null = element;

	if (!document.documentElement.contains(el)) return null;

	do {
		const legacyEl = el as LegacyElement;

		const method =
			legacyEl.matches ||
			legacyEl.msMatchesSelector ||
			legacyEl.webkitMatchesSelector;

		if (method?.call(el, selector)) return el;

		el = (el.parentElement || el.parentNode) as Element | null;
	} while (el !== null && el.nodeType === 1);

	console.error("Your browser is not supported");
	return null;
}

function getRootNode(element?: Node | null): HTMLElement {
	if (!element) {
		return document.body;
	}

	if (!isShadowDomSupported()) {
		return document.body;
	}

	let currentElement: Node | null = element;

	while (currentElement.parentNode) {
		currentElement = currentElement.parentNode;

		if (currentElement instanceof ShadowRoot) {
			return currentElement.host as HTMLElement;
		}
	}

	return document.body;
}

function hasShadowParent(element: Node): boolean {
	return !!getRootNode(element);
}

const domHelpers = {
	getAbsoluteLeft(htmlObject: HTMLElement): number {
		const offsetLeft = this.getOffset(htmlObject).left;
		const paddingLeft = parseInt(window.getComputedStyle(htmlObject).paddingLeft, 10) || 0;

		return offsetLeft + paddingLeft;
	},

	getAbsoluteTop(htmlObject: HTMLElement): number {
		const offsetTop = this.getOffset(htmlObject).top;
		const paddingTop = parseInt(window.getComputedStyle(htmlObject).paddingTop, 10) || 0;

		return offsetTop + paddingTop;
	},

	getOffsetSum(elem: HTMLElement): OffsetPosition {
		let top = 0;
		let left = 0;
		let currentElem: HTMLElement | null = elem;

		while (currentElem) {
			top += parseInt(String(currentElem.offsetTop), 10);
			left += parseInt(String(currentElem.offsetLeft), 10);
			currentElem = currentElem.offsetParent as HTMLElement | null;
		}

		return { top, left };
	},

	getOffsetRect(elem: HTMLElement): OffsetPosition {
		const box = elem.getBoundingClientRect();

		let top = 0;
		let left = 0;

		if (!/Mobi/.test(navigator.userAgent)) {
			const body = document.body;
			const docElem = document.documentElement;
			const scrollTop = window.pageYOffset || docElem.scrollTop || body.scrollTop;
			const scrollLeft = window.pageXOffset || docElem.scrollLeft || body.scrollLeft;
			const clientTop = docElem.clientTop || body.clientTop || 0;
			const clientLeft = docElem.clientLeft || body.clientLeft || 0;

			top = box.top + scrollTop - clientTop;
			left = box.left + scrollLeft - clientLeft;
		} else {
			const dummy = document.createElement("div");

			dummy.style.position = "absolute";
			dummy.style.left = "0px";
			dummy.style.top = "0px";
			dummy.style.width = "1px";
			dummy.style.height = "1px";

			document.body.appendChild(dummy);

			const dummyBox = dummy.getBoundingClientRect();

			top = box.top - dummyBox.top;
			left = box.left - dummyBox.left;

			dummy.parentNode?.removeChild(dummy);
		}

		return {
			top: Math.round(top),
			left: Math.round(left),
		};
	},

	getOffset(elem: HTMLElement): OffsetPosition {
		return this.getOffsetSum(elem);
	},

	closest(element: LegacyElement | null, selector: string): Element | null {
		if (!element || !selector) {
			return null;
		}

		return closest(element, selector);
	},

	insertAfter(newNode: Node, referenceNode: Node): void {
		if (!referenceNode.parentNode) return;

		if (referenceNode.nextSibling) {
			referenceNode.parentNode.insertBefore(newNode, referenceNode.nextSibling);
		} else {
			referenceNode.parentNode.appendChild(newNode);
		}
	},

	remove(node?: Node | null): void {
		if (node?.parentNode) {
			node.parentNode.removeChild(node);
		}
	},

	isChildOf(child: Node, parent: Node): boolean {
		return parent.contains(child);
	},

	getFocusableNodes,
	getClassName,
	locateCss,
	getRootNode,
	hasShadowParent,
	isShadowDomSupported,
	getActiveElement,
	getRelativeEventPosition,
	getTargetNode,
	getNodePosition
};

export default domHelpers;